"""Collection of tools for device control"""

from typing import Any

from anthropic.types.beta import BetaToolUnionParam

from .base import BaseAnthropicTool, ToolError, ToolResult
from .mac_tool import MacTool
from .ios_tool import IOSTool

class ToolCollection:
    """Collection of control tools"""

    def __init__(self):
        self.tools = [
            MacTool(),
            IOSTool(),
        ]
        self.tool_map = {tool.to_params()["name"]: tool for tool in self.tools}

    def to_params(self) -> list[BetaToolUnionParam]:
        """Get API parameters for all tools"""
        return [tool.to_params() for tool in self.tools]

    async def run(self, *, name: str, tool_input: dict[str, Any]) -> ToolResult:
        """Execute a tool by name"""
        tool = self.tool_map.get(name)
        if not tool:
            return ToolResult(error=f"Invalid tool: {name}")

        try:
            return await tool(**tool_input)
        except ToolError as e:
            return ToolResult(error=e.message)

from abc import ABCMeta, abstractmethod
from dataclasses import dataclass, fields, replace
from typing import Any, Optional

from anthropic.types.beta import BetaToolUnionParam

@dataclass(frozen=True)
class ToolResult:
    """Result from tool execution"""
    output: Optional[str] = None
    error: Optional[str] = None 
    base64_image: Optional[str] = None
    system: Optional[str] = None

    def __bool__(self):
        return any(getattr(self, field.name) for field in fields(self))

    def replace(self, **kwargs):
        return replace(self, **kwargs)

class ToolError(Exception):
    """Tool execution error"""
    def __init__(self, message: str):
        self.message = message

class BaseAnthropicTool(metaclass=ABCMeta):
    """Base class for Anthropic tools"""

    @abstractmethod
    async def __call__(self, **kwargs) -> Any:
        """Execute the tool"""
        pass

    @abstractmethod
    def to_params(self) -> BetaToolUnionParam:
        """Convert tool to API parameters"""
        pass

"""Safety checks for Mac automation"""

import pyautogui
from typing import Tuple

class SafetyChecker:
    """Validates automation actions for safety"""

    # Sensitive UI elements that should not be clicked
    SENSITIVE_REGIONS = [
        # Add coordinates of sensitive UI areas
    ]

    @staticmethod
    def is_safe_click(x: int, y: int) -> Tuple[bool, str]:
        """Check if clicking at coordinates is safe"""
        # Check screen bounds
        screen_width, screen_height = pyautogui.size()
        if x < 0 or x > screen_width or y < 0 or y > screen_height:
            return False, "Coordinates out of screen bounds"

        # Check sensitive regions
        for region in SafetyChecker.SENSITIVE_REGIONS:
            if point_in_region((x, y), region):
                return False, "Cannot click in sensitive UI region"

        return True, ""

    @staticmethod
    def is_safe_type(text: str) -> Tuple[bool, str]:
        """Check if text input is safe"""
        # Prevent dangerous commands
        dangerous_patterns = [
            "sudo",
            "rm -rf",
            "mkfs",
            "dd",
            ">",
            "|",
        ]

        for pattern in dangerous_patterns:
            if pattern in text.lower():
                return False, f"Dangerous pattern detected: {pattern}"

        return True, ""

def point_in_region(point: Tuple[int, int], region: Tuple[int, int, int, int]) -> bool:
    """Check if point is inside region"""
    x, y = point
    rx, ry, rw, rh = region
    return rx <= x <= rx + rw and ry <= y <= ry + rh

"""Context managers for device operations"""

import asyncio
from contextlib import asynccontextmanager
from typing import AsyncGenerator, Optional

from ..tools.device_manager import DeviceManager
from ..utils.state import DeviceStatus
from .logging import setup_logging

logger = setup_logging()

@asynccontextmanager
async def device_operation(
    device_manager: DeviceManager,
    device_type: str,
    timeout: Optional[float] = None
) -> AsyncGenerator[bool, None]:
    """Context manager for safe device operations"""
    try:
        # Ensure device is ready
        if not await device_manager.ensure_device_ready(device_type):
            logger.error(f"Failed to prepare {device_type} device")
            yield False
            return

        # Set timeout if specified
        if timeout:
            try:
                async with asyncio.timeout(timeout):
                    yield True
            except asyncio.TimeoutError:
                logger.error(f"Operation timed out after {timeout}s")
                if device_type == "mac":
                    device_manager.state.update_mac_state(
                        DeviceStatus.ERROR,
                        "Operation timed out"
                    )
                else:
                    device_manager.state.update_ios_state(
                        DeviceStatus.ERROR,
                        "Operation timed out"
                    )
                yield False
        else:
            yield True

    except Exception as e:
        logger.error(f"Device operation failed: {str(e)}")
        if device_type == "mac":
            device_manager.state.update_mac_state(DeviceStatus.ERROR, str(e))
        else:
            device_manager.state.update_ios_state(DeviceStatus.ERROR, str(e))
        yield False

    finally:
        # Cleanup if needed
        if device_type == "ios":
            device_manager.cleanup()

"""Cleanup utilities"""

import os
import shutil
from datetime import datetime, timedelta
from pathlib import Path
from typing import Optional

from ..config import TEMP_DIR

class CleanupManager:
    """Manage temporary files and resources"""

    def __init__(self, max_age: Optional[timedelta] = None):
        self.max_age = max_age or timedelta(hours=1)

    def cleanup_temp_files(self):
        """Remove old temporary files"""
        now = datetime.now()

        for file in TEMP_DIR.glob("*"):
            if not file.is_file():
                continue

            # Check file age
            mtime = datetime.fromtimestamp(file.stat().st_mtime)
            if now - mtime > self.max_age:
                try:
                    file.unlink()
                except OSError:
                    pass

    def cleanup_all(self):
        """Perform full cleanup"""
        # Remove temp directory
        try:
            shutil.rmtree(TEMP_DIR)
            TEMP_DIR.mkdir(exist_ok=True)
        except OSError:
            pass

        # Kill any lingering processes
        self._cleanup_processes()

    def _cleanup_processes(self):
        """Kill related processes"""
        processes = [
            "appium",
            "WebDriverAgent",
        ]

        for proc in processes:
            try:
                os.system(f"pkill -f {proc}")
            except:
                pass

"""Utility decorators"""

import asyncio
import functools
from typing import Any, Callable, Optional, Type, TypeVar

from .logging import setup_logging

logger = setup_logging()

T = TypeVar('T')

def with_retries(
    retries: int = 3,
    delay: float = 1.0,
    exceptions: tuple[Type[Exception], ...] = (Exception,),
    logger = None
):
    """Retry decorator for async functions"""
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(func)
        async def wrapper(*args: Any, **kwargs: Any) -> T:
            last_error: Optional[Exception] = None

            for attempt in range(retries):
                try:
                    return await func(*args, **kwargs)
                except exceptions as e:
                    last_error = e
                    if logger:
                        logger.warning(
                            f"Attempt {attempt + 1}/{retries} failed: {str(e)}"
                        )
                    if attempt < retries - 1:
                        await asyncio.sleep(delay)

            if last_error:
                raise last_error

        return wrapper
    return decorator

def log_execution(logger = None):
    """Log function execution with timing"""
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(func)
        async def wrapper(*args: Any, **kwargs: Any) -> T:
            start = asyncio.get_event_loop().time()
            try:
                result = await func(*args, **kwargs)
                elapsed = asyncio.get_event_loop().time() - start
                if logger:
                    logger.debug(
                        f"{func.__name__} completed in {elapsed:.2f}s"
                    )
                return result
            except Exception as e:
                elapsed = asyncio.get_event_loop().time() - start
                if logger:
                    logger.error(
                        f"{func.__name__} failed after {elapsed:.2f}s: {str(e)}"
                    )
                raise
        return wrapper
    return decorator

"""iOS device connection management"""

import asyncio
import atexit
import subprocess
from typing import Optional

from appium import webdriver
from appium.webdriver.webdriver import WebDriver

from ..config import CONFIG

class IOSConnectionManager:
    """Manages Appium server and device connections"""

    def __init__(self):
        self.driver: Optional[WebDriver] = None
        self.appium_process: Optional[subprocess.Popen] = None
        self._setup_cleanup()

    def _setup_cleanup(self):
        """Ensure cleanup on exit"""
        atexit.register(self.cleanup)

    async def ensure_appium_running(self):
        """Start Appium server if not running"""
        if self.appium_process is None:
            try:
                self.appium_process = subprocess.Popen(
                    ["appium"],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE
                )
                # Wait for server to start
                await asyncio.sleep(5)
            except Exception as e:
                raise ConnectionError(f"Failed to start Appium: {e}")

    async def connect_device(self) -> WebDriver:
        """Connect to iOS device/simulator"""
        await self.ensure_appium_running()

        capabilities = {
            'platformName': 'iOS',
            'automationName': 'XCUITest',
            'deviceName': 'iPhone Simulator',
        }

        if device_id := CONFIG["ios_device_id"]:
            capabilities['udid'] = device_id

        try:
            self.driver = webdriver.Remote(
                'http://localhost:4723/wd/hub',
                capabilities
            )
            return self.driver
        except Exception as e:
            raise ConnectionError(f"Failed to connect to iOS device: {e}")

    def cleanup(self):
        """Clean up connections"""
        if self.driver:
            try:
                self.driver.quit()
            except:
                pass
            self.driver = None

        if self.appium_process:
            try:
                self.appium_process.terminate()
            except:
                pass
            self.appium_process = None

